using System;
using System.IO;
using System.Linq;
using Touchfish;
public static partial class RuleTests {
 static void Paladin(){
  var all=catalog.Deckable(catalog.Pool("classic-2014"));Check(all.Count(c=>c.CardClass=="PALADIN")==25&&all.Where(c=>c.CardClass=="PALADIN").All(matchRules.Supports),"All 25 Paladin cards supported");
  var g=MatchFixture("PALADIN");g.Players[0].Health=20;g.Summon(0,"VAN_EX1_350");Check(g.Play(0,Hand(g,"CS2_088")).Success&&g.Players[0].Health==26,"Guardian restores six without Velen battlecry amplification");
  g=MatchFixture("PALADIN");g.Players[0].Health=20;g.Summon(0,"VAN_EX1_591");g.Play(0,Hand(g,"CS2_088"));Check(g.Players[0].Health==14,"Guardian healing respects Auchenai conversion");
  g=MatchFixture("PALADIN");g.Play(0,Hand(g,"EX1_366"));var body=g.Summon(0,"VAN_CS2_182");Check(g.AttackValue(body)==5&&body.Health==6&&g.Players[0].WeaponDurability==4,"Sword buffs actual summon and consumes one durability");var enemy=g.Summon(1,"VAN_CS2_182");Check(enemy.Health==5&&g.Players[0].WeaponDurability==4,"Sword ignores opponent summons");g.HeroPower(0);Check(g.Players[0].Board.Last().Health==2&&g.Players[0].WeaponDurability==3,"Sword buffs hero power recruit");g.Play(0,Hand(g,"EX1_506"));Check(g.Players[0].WeaponDurability==1&&g.Players[0].Board.Last().Health==2,"Sword applies to played body and battlecry token independently");body=g.Summon(0,"VAN_CS2_182");Check(body.Health==6&&g.Players[0].WeaponId==null&&g.Graveyard.Count(e=>e.Reason==GraveyardReason.WeaponDestroyed)==1,"Last durability still buffs then destroys weapon once");
  g=MatchFixture("PALADIN");g.Play(0,Hand(g,"EX1_366"));body=g.Summon(0,"VAN_CS2_182");int durability=g.Players[0].WeaponDurability;g.Transform(new MatchTarget(0,body.Id),"GAME_FROG");Check(g.Players[0].Board.Single().Health==1&&g.Players[0].WeaponDurability==durability,"Transformation is not a Sword summon trigger");
  g=MatchFixture("PALADIN");g.Play(0,Hand(g,"EX1_366"));for(int n=0;n<7;n++)g.Summon(0,"VAN_CS2_231");int count=g.Graveyard.Count;Check(g.Summon(0,"VAN_CS2_231")==null&&g.Graveyard.Count==count,"Failed summon causes no weapon transaction");
  g=MatchFixture("WARRIOR");g.Play(0,Hand(g,"EX1_366")); // cross-class weapon remains illegal without trusted generation
  Check(g.Players[0].WeaponId==null&&g.Players[0].Mana==10,"Sword does not relax deck or ordinary hand class restrictions");
  g=MatchFixture("PALADIN");g.Play(0,Hand(g,"EX1_366"));body=g.Summon(0,"VAN_EX1_556");g.Damage(new MatchTarget(0,body.Id),20);g.Cleanup();Check(g.Players[0].Board.Single().Health==2&&g.Players[0].WeaponDurability==3,"Sword buffs deathrattle summon");
 }
 static void Shaman(){
  var all=catalog.Deckable(catalog.Pool("classic-2014"));Check(all.Count(c=>c.CardClass=="SHAMAN")==25&&all.Where(c=>c.CardClass=="SHAMAN").All(matchRules.Supports),"All 25 Shaman cards supported");
  var g=MatchFixture("SHAMAN");g.Summon(0,"VAN_EX1_563");g.Summon(0,"VAN_EX1_350");g.Play(0,Hand(g,"CS2_042"),new MatchTarget(1));Check(g.Players[1].Health==27,"Fire Elemental battlecry ignores spell power and Velen");
  g=MatchFixture("SHAMAN");g.Players[0].Deck.Clear();g.Players[0].Deck.Add("VAN_CS2_182");g.Play(0,Hand(g,"CS2_053"));var discounted=g.Players[0].Hand.Single();Check(discounted.CostAdjustment==-3&&g.HandCost(0,discounted)==1,"Far Sight discount attaches to actual drawn hand instance");int other=Hand(g,"CS2_182");Check(g.HandCost(0,g.Players[0].Hand.Single(h=>h.Id==other))==4,"Other copy remains full cost");g.Play(0,discounted.Id);var body=g.Players[0].Board.Single();g.ReturnToHand(new MatchTarget(0,body.Id));Check(g.Players[0].Hand.All(h=>g.HandCost(0,h)==4),"Far Sight discount resets on replay and bounce");
  g=MatchFixture("SHAMAN");g.Players[0].Deck.Clear();g.Play(0,Hand(g,"CS2_053"));Check(g.Players[0].Hand.Count==0&&g.Players[0].Fatigue==1,"Empty Far Sight applies fatigue without creating discounted card");
  g=MatchFixture("SHAMAN");g.Players[0].Deck.Clear();g.Players[0].Deck.Add("VAN_CS2_231");g.Summon(0,"VAN_EX1_559");for(int n=0;n<9;n++)Hand(g,"CS2_182");g.Play(0,Hand(g,"CS2_053"));Check(g.Players[0].Hand.Count==10&&g.Players[0].Deck.Count==0&&g.Players[0].Hand.All(h=>h.CostAdjustment==0),"Far Sight burn does not discount unrelated existing hand");
  g=MatchFixture("SHAMAN");var totem=g.Summon(0,"VAN_CS2_051");var tide=g.Summon(0,"VAN_EX1_575");body=g.Summon(0,"VAN_CS2_182");var foe=g.Summon(1,"VAN_CS2_051");g.Play(0,Hand(g,"EX1_244"));Check(totem.MaxHealth==4&&tide.MaxHealth==5&&body.MaxHealth==5&&foe.MaxHealth==2,"Totemic Might buffs all own totems only");g.Silence(new MatchTarget(0,totem.Id));Check(totem.MaxHealth==2,"Silence removes Totemic Might buff");
  g=MatchFixture("SHAMAN");body=g.Summon(1,"VAN_EX1_556");g.Play(0,Hand(g,"CS2_038"),new MatchTarget(1,body.Id));g.Play(0,Hand(g,"EX1_246"),new MatchTarget(1,body.Id));var frog=g.Players[1].Board.Single();Check(frog.CardId=="GAME_FROG"&&frog.Health==1&&frog.Taunt&&g.AttackValue(frog)==0&&frog.AncestralSpirits==0&&g.Graveyard.Count==2,"Hex replaces minion with unenchanted Frog without deathrattle");
  g=MatchFixture("SHAMAN");body=g.Summon(1,"VAN_CS2_231");body.SummonTurn=0;g.Play(0,Hand(g,"EX1_334"),new MatchTarget(1,body.Id));g.Play(0,Hand(g,"EX1_246"),new MatchTarget(0,body.Id));frog=g.Players[0].Board.Single();g.EndTurn();Check(frog.Owner==1,"Temporary control returns transformed Frog at turn end");
  g=MatchFixture("SHAMAN");var unbound=g.Summon(0,"VAN_EX1_258");g.Play(0,Hand(g,"EX1_238"),new MatchTarget(1));Check(g.AttackValue(unbound)==3&&unbound.MaxHealth==5&&g.Players[0].Overload==1,"Unbound grows once for own overload spell");g.Play(0,Hand(g,"EX1_243"));Check(g.AttackValue(unbound)==4&&unbound.MaxHealth==6&&g.Players[0].Overload==3,"Unbound grows once for overload minion irrespective of overload amount");g.Play(0,Hand(g,"GAME_COIN"));Check(g.AttackValue(unbound)==4,"Unbound ignores non-overload card");g.Silence(new MatchTarget(0,unbound.Id));g.Players[0].Mana=10;g.Play(0,Hand(g,"EX1_247"));Check(g.AttackValue(unbound)==2&&unbound.MaxHealth==4,"Silenced Unbound stops growing");
  g=MatchFixture("SHAMAN");body=g.Summon(0,"VAN_CS2_182");g.Play(0,Hand(g,"EX1_587"),new MatchTarget(0,body.Id));Check(g.HasWindfury(body),"Windspeaker grants permanent windfury");g.EndTurn();g.EndTurn();Check(g.Attack(0,body.Id,new MatchTarget(1)).Success&&g.Attack(0,body.Id,new MatchTarget(1)).Success&&!g.Attack(0,body.Id,new MatchTarget(1)).Success,"Granted Windfury allows exactly two attacks");
  g=MatchFixture("SHAMAN");g.Summon(0,"VAN_CS2_231");body=g.Summon(0,"VAN_CS2_182");g.Summon(0,"VAN_CS2_179");g.Buff(new MatchTarget(0,body.Id),3,4);g.Play(0,Hand(g,"CS2_038"),new MatchTarget(0,body.Id));g.Damage(new MatchTarget(0,body.Id),20);g.Cleanup();var restored=g.Players[0].Board[1];Check(restored.CardId=="VAN_CS2_182"&&restored.Id!=body.Id&&restored.Health==5&&g.AttackValue(restored)==4&&restored.AncestralSpirits==0,"Ancestral returns base fresh body at death position without recursive enchantment");
  g=MatchFixture("SHAMAN");body=g.Summon(0,"VAN_CS2_182");g.Play(0,Hand(g,"CS2_038"),new MatchTarget(0,body.Id));g.Play(0,Hand(g,"CS2_038"),new MatchTarget(0,body.Id));var copy=new BattleUnit();BattleUnitCopies.Copy(body,copy);copy.Enchantments.Items.Clear();Check(body.AncestralSpirits==2,"Ancestral enchantments copy independently");var view=LanProtocol.ReadView(catalog,LanProtocol.Copy(LanProtocol.View(g,1,"shaman",1)));Check(view.Players[0].Board.Single().AncestralSpirits==2,"Ancestral enchantment count visible in public board snapshot");g.Damage(new MatchTarget(0,body.Id),20);g.Cleanup();Check(g.Players[0].Board.Count==2&&g.Players[0].Board.All(u=>u.AncestralSpirits==0),"Multiple Ancestral grants each summon one base copy");
  g=MatchFixture("SHAMAN");body=g.Summon(0,"VAN_EX1_556");g.Play(0,Hand(g,"CS2_038"),new MatchTarget(0,body.Id));g.Damage(new MatchTarget(0,body.Id),20);g.Cleanup();Check(g.Players[0].Board.Count==2&&g.Players[0].Board[0].CardId=="VAN_skele21"&&g.Players[0].Board[1].CardId=="VAN_EX1_556","Native deathrattle and Ancestral both resolve");
  g=MatchFixture("SHAMAN");body=g.Summon(0,"VAN_CS2_182");g.Play(0,Hand(g,"CS2_038"),new MatchTarget(0,body.Id));g.Silence(new MatchTarget(0,body.Id));g.Damage(new MatchTarget(0,body.Id),20);g.Cleanup();Check(g.Players[0].Board.Count==0,"Silence removes existing Ancestral grant");
  g=MatchFixture("SHAMAN");body=g.Summon(0,"VAN_CS2_182");g.Silence(new MatchTarget(0,body.Id));g.Play(0,Hand(g,"CS2_038"),new MatchTarget(0,body.Id));g.Damage(new MatchTarget(0,body.Id),20);g.Cleanup();Check(g.Players[0].Board.Count==1,"Ancestral can be newly granted after previous silence");
  g=MatchFixture("SHAMAN");body=g.Summon(1,"VAN_CS2_182");g.Play(0,Hand(g,"CS2_038"),new MatchTarget(1,body.Id));g.Damage(new MatchTarget(1,body.Id),20);g.Cleanup();Check(g.Players[1].Board.Count==1&&g.Players[0].Board.Count==0,"Ancestral follows current controller rather than spell caster");
  g=MatchFixture("SHAMAN");body=g.Summon(0,"VAN_CS2_182");g.Play(0,Hand(g,"CS2_038"),new MatchTarget(0,body.Id));g.Play(0,Hand(g,"EX1_158"));g.Damage(new MatchTarget(0,body.Id),20);g.Cleanup();Check(g.Players[0].Board[0].CardId=="VAN_CS2_182"&&g.Players[0].Board[1].CardId=="VAN_EX1_tk9","Mixed added deathrattles follow grant order");
  g=MatchFixture("MAGE","SHAMAN");g.Play(0,Hand(g,"EX1_287"));g.EndTurn();unbound=g.Summon(1,"VAN_EX1_258");g.Players[1].Mana=10;g.Play(1,Hand(g,"EX1_238",1),new MatchTarget(0));Check(g.Players[0].Health==30&&g.Players[1].Overload==0&&g.AttackValue(unbound)==3,"Countered overload spell grows Unbound without applying overload effect");
  g=MatchFixture("SHAMAN");body=g.Summon(0,"VAN_EX1_556");for(int n=0;n<6;n++)g.Summon(0,"VAN_CS2_231");g.Play(0,Hand(g,"CS2_038"),new MatchTarget(0,body.Id));g.Damage(new MatchTarget(0,body.Id),20);g.Cleanup();Check(g.Players[0].Board.Count==7&&g.Players[0].Board.Any(u=>u.CardId=="VAN_skele21")&&g.Players[0].Board.All(u=>u.CardId!="VAN_EX1_556"),"Ancestral obeys seven slots when native deathrattle uses freed slot");
  var folder=Path.Combine(Environment.CurrentDirectory,"previews");Directory.CreateDirectory(folder);JsonData.Write(Path.Combine(folder,"match-rule-coverage.json"),new{SupportedCards=all.Count(matchRules.Supports),TotalCards=all.Count,Cards=all.Select(c=>new{Id=c.Id,Name=c.Name,Supported=matchRules.Supports(c)}).ToArray(),Scope="All classic cards; Paladin/Shaman 25/25"});
 }
}
